+// Configuración del conector ERP: ERP_TIMEOUT_MS (ms, entero positivo; por defecto 5000).
+export function configuracionErp(env = process.env) {
+  const crudo = env.ERP_TIMEOUT_MS;
+  if (crudo === undefined) return { timeoutMs: 5000 };
+  if (!/^[1-9]\d*$/.test(crudo.trim())) throw new RangeError(`ERP_TIMEOUT_MS inválido: "${crudo}" (se espera un entero positivo en milisegundos)`);
+  return { timeoutMs: Number(crudo.trim()) };
+}
